  g.fillStyle = color; g.beginPath(); g.moveTo(-50, 14); g.bezierCurveTo(-50, -40, 30, -52, 56, -22); g.bezierCurveTo(100, -10, 104, 18, 70, 26); g.bezierCurveTo(40, 40, -30, 44, -50, 14); g.closePath(); g.fill();
