      D.sprinkle(g, r, 8, [860, 250, 140, 70], (x, y) => { g.save(); g.translate(x, y); g.rotate(r() * 3); D.rr(g, -7, -4, 14, 8, 1.5, '#ffe9a8', '#c98a4f', 1); g.restore(); });
      // tabelalar
