        for (let i = 0; i < 12; i++) { const b = a + i / 12 * TAU + .13, x = X + Math.cos(b) * R, y = Y + Math.sin(b) * R; D.rr(g, x - 7, y - 2, 14, 12, 4, cab[i % 6], '#4a2a6a', 1.5); D.circle(g, x, y - 3, 2.2, '#fff7c2'); }
        D.circle(g, X, Y, 7, '#ffd84a', '#6a3fb5', 2);
