    for (let i = 0; i < 6; i++) { const x = 670 + i * 20; g.lineWidth = 4; g.beginPath(); g.moveTo(x, 770 - i * 3); g.quadraticCurveTo(x - 6, 795, x + 4, 808); g.stroke(); }
