  st.t0 = Date.now(); st.relit = {}; st.radarLeft = RADAR_N; st.radarReady = 0; st.rattleAt = 0;
  st.spos = { x: (map.spawn || [800, 900])[0], y: (map.spawn || [800, 900])[1], h: -Math.PI / 2, t: Date.now() }; st.bot = null;
