  ctx.emit({ t: 'radar', x: Math.round(p.x), y: Math.round(p.y), cnt }, `📡 Radar taraması: ${cnt ? `yakında ${cnt} saklanan var!` : 'yakında kimse yok.'}`, 'gold');
