  const hits = hiderIds(st).filter(k => { const h = st.hiders[k]; return !h.found && h.spot && dist(x, y, cur[k].x, cur[k].y) <= PROBE_R + propR(h) * .4; });
  st.probes.push({ x, y, hit: hits.length > 0 });
