    hits.forEach(k => { st.hiders[k].found = true; st.hiders[k].foundAt = now; });
    const found = hits.map(k => ({ pi: k, name: pname(st, k), color: st.players[k].color, x: Math.round(cur[k].x), y: Math.round(cur[k].y) }));
