const now = () => performance.now();
const mmss = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
const lookFrom = m => ({ shape: m.shape, x: m.spot ? m.spot.x : 0, y: m.spot ? m.spot.y : 0, rot: m.rot, scale: m.scale, c1: m.c1, c2: m.c2, pat: m.pat });
