  for (let i = 0; i < 1600; i++) { const x = r() * W, y = map.top + r() * (H - map.top); g.fillStyle = r() < .5 ? 'rgba(0,0,0,.035)' : 'rgba(255,255,255,.045)'; g.fillRect(x, y, 1.5 + r() * 2, 1.5 + r() * 2); }
