    const k = Math.min(2, Math.max(1.25, (window.devicePixelRatio || 1) * .9));
    const c = document.createElement('canvas'); c.width = Math.round(W * k); c.height = Math.round(H * k);
    const g = c.getContext('2d'); g.scale(k, k);
