    polish(g, map);
    const th = document.createElement('canvas'); th.width = 320; th.height = 200; th.getContext('2d').drawImage(c, 0, 0, 320, 200);
    scene = { mapId, seed, map, ground: c, k, thumb: th, decoys: decoysOf(mapId, seed), mood: buildMood(map) };
