  const m = 150, x0 = Math.min(...pts.map(p => p.x)) - m, x1 = Math.max(...pts.map(p => p.x)) + m, y0 = Math.min(...pts.map(p => p.y)) - m - 40, y1 = Math.max(...pts.map(p => p.y)) + m;
