const toWorld = (sx, sy) => [cam.x + sx / cam.s, cam.y + sy / cam.s];
function toClient(x, y) { const r = cv.getBoundingClientRect(); return [r.left + (x - cam.x) * cam.s, r.top + (y - cam.y) * cam.s]; }
