  if (ice) { const k = Math.min(1, dt * 1.5); av.vx = (av.vx || 0) + (tvx - (av.vx || 0)) * k; av.vy = (av.vy || 0) + (tvy - (av.vy || 0)) * k; }
  else { av.vx = tvx; av.vy = tvy; }
